import{_ as s,o as e,c as n,a5 as i}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"78. Crash Analysis and Core Dumps","description":"The Little Book of C — 78. Crash Analysis and Core Dumps","frontmatter":{"title":"78. Crash Analysis and Core Dumps","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Debugging Testing Profiling"],"description":"The Little Book of C — 78. Crash Analysis and Core Dumps","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":78,"sidebarWeight":78,"lang":"en-US","alternateEn":"/posts/c教程/en-US/08-Debugging Testing Profiling/078-Crash Analysis and Core Dumps","alternateZh":"/posts/c教程/zh-CN/08-调试测试与 profiling/078-Crash Analysis and Core Dumps"},"headers":[],"relativePath":"posts/c教程/en-US/08-Debugging Testing Profiling/078-Crash Analysis and Core Dumps.md","filePath":"posts/c教程/en-US/08-Debugging Testing Profiling/078-Crash Analysis and Core Dumps.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/en-US/08-Debugging Testing Profiling/078-Crash Analysis and Core Dumps.md"};function p(l,a,o,c,r,d){return e(),n("div",null,[...a[0]||(a[0]=[i(`<p>[中文版本](/posts/c教程/zh-CN/08-调试测试与 profiling/078-Crash Analysis and Core Dumps)</p><p>Even with careful coding and testing, programs crash. In C, a crash is your system’s way of saying “you touched something you shouldn’t have.” The good news is you can analyze crashes scientifically using core dumps, snapshots of your program’s memory at the moment of failure.</p><p>Learning how to read them is an essential skill for every systems programmer.</p><h4 id="step-1-what-is-a-core-dump" tabindex="-1">Step 1. What Is a Core Dump? <a class="header-anchor" href="#step-1-what-is-a-core-dump" aria-label="Permalink to &quot;Step 1. What Is a Core Dump?&quot;">​</a></h4><p>A core dump is a file that captures your program’s state (stack, registers, memory) at the time it crashed. You can inspect it later using a debugger like gdb to see what went wrong.</p><p>Common crash signals that generate core dumps:</p><ul><li>SIGSEGV – invalid memory access (segmentation fault)</li><li>SIGABRT – failed assertion</li><li>SIGFPE – arithmetic error (like division by zero)</li><li>SIGILL – illegal instruction</li></ul><h4 id="step-2-enabling-core-dumps" tabindex="-1">Step 2. Enabling Core Dumps <a class="header-anchor" href="#step-2-enabling-core-dumps" aria-label="Permalink to &quot;Step 2. Enabling Core Dumps&quot;">​</a></h4><p>By default, modern systems limit or disable them. Enable them using:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ulimit -c unlimited</span></span></code></pre></div><p>Check:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ulimit -a | grep core</span></span></code></pre></div><p>Now when your program crashes, a file named<code>core</code> or<code>core. </code> will appear.</p><h4 id="step-3-a-crashing-example" tabindex="-1">Step 3. A Crashing Example <a class="header-anchor" href="#step-3-a-crashing-example" aria-label="Permalink to &quot;Step 3. A Crashing Example&quot;">​</a></h4><p>Let’s make a simple crash:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int *p = NULL;</span></span>
<span class="line"><span>    *p = 42;</span><span>  // crash: dereferencing null pointer</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc crash.c -g -o crash</span></span>
<span class="line"><span>./crash</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Segmentation fault (core dumped)</span></span></code></pre></div><p>A<code>core</code> file is now created in your directory.</p><h4 id="step-4-opening-the-core-dump-in-gdb" tabindex="-1">Step 4. Opening the Core Dump in gdb <a class="header-anchor" href="#step-4-opening-the-core-dump-in-gdb" aria-label="Permalink to &quot;Step 4. Opening the Core Dump in gdb&quot;">​</a></h4><p>Use gdb to inspect what happened:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gdb ./crash core</span></span></code></pre></div><p>You’ll see:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Core was generated by \`./crash&#39;.</span></span>
<span class="line"><span>Program terminated with signal SIGSEGV, Segmentation fault.</span></span>
<span class="line"><span>#0  0x0000000000401136 in main () at crash.c:5</span></span>
<span class="line"><span>5       *p = 42;</span></span></code></pre></div><p>This tells you the exact line where the program crashed.</p><h4 id="step-5-inspecting-variables-and-stack" tabindex="-1">Step 5. Inspecting Variables and Stack <a class="header-anchor" href="#step-5-inspecting-variables-and-stack" aria-label="Permalink to &quot;Step 5. Inspecting Variables and Stack&quot;">​</a></h4><p>Within gdb:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) bt</span></span></code></pre></div><p>Shows the backtrace, the call stack at the moment of crash.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#0  main () at crash.c:5</span></span></code></pre></div><p>You can inspect variables:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) info locals</span></span>
<span class="line"><span>(gdb) print p</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$1 = (int *) 0x0</span></span></code></pre></div><h4 id="step-6-a-more-complex-example" tabindex="-1">Step 6. A More Complex Example <a class="header-anchor" href="#step-6-a-more-complex-example" aria-label="Permalink to &quot;Step 6. A More Complex Example&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>void f3(int *p) {</span></span>
<span class="line"><span>    *p = 7;</span><span>  // likely crash here</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>void f2(int *p) {</span></span>
<span class="line"><span>    f3(p);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>void f1(void) {</span></span>
<span class="line"><span>    int *x = NULL;</span></span>
<span class="line"><span>    f2(x);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    f1();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Run it, crash it, then:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gdb ./crash core</span></span></code></pre></div><p>Inside gdb:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) bt</span></span>
<span class="line"><span>#0  f3 (p=0x0) at crash.c:4</span></span>
<span class="line"><span>#1  f2 (p=0x0) at crash.c:8</span></span>
<span class="line"><span>#2  f1 () at crash.c:12</span></span>
<span class="line"><span>#3  main () at crash.c:16</span></span></code></pre></div><p>You can see the entire call chain that led to the null dereference.</p><h4 id="step-7-debugging-optimized-builds" tabindex="-1">Step 7. Debugging Optimized Builds <a class="header-anchor" href="#step-7-debugging-optimized-builds" aria-label="Permalink to &quot;Step 7. Debugging Optimized Builds&quot;">​</a></h4><p>When you compile with<code>-O2</code> or<code>-O3</code>, the compiler may inline or reorder code, making debugging harder. For debugging, always use:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -g -O0 crash.c -o crash</span></span></code></pre></div><p>The<code>-g</code> flag keeps symbol information (file names, line numbers). Without it, gdb can’t tell you much beyond addresses.</p><h4 id="step-8-controlling-core-dump-location" tabindex="-1">Step 8. Controlling Core Dump Location <a class="header-anchor" href="#step-8-controlling-core-dump-location" aria-label="Permalink to &quot;Step 8. Controlling Core Dump Location&quot;">​</a></h4><p>Change where dumps are stored:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo sysctl -w kernel.core_pattern=/tmp/core.%e.%p</span></span></code></pre></div><p>This example saves them in<code>/tmp</code> with program name and process ID:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/tmp/core.crash.1234</span></span></code></pre></div><h4 id="step-9-crash-analysis-workflow" tabindex="-1">Step 9. Crash Analysis Workflow <a class="header-anchor" href="#step-9-crash-analysis-workflow" aria-label="Permalink to &quot;Step 9. Crash Analysis Workflow&quot;">​</a></h4><p>Enable dumps:<code>ulimit -c unlimited</code></p><p>Run program until it crashes</p><p>Locate core file</p><p>Analyze with gdb:</p><ul><li><code>bt</code> for stack trace</li><li><code>info locals</code> for local vars</li><li><code>frame </code> to inspect each stack frame</li><li><code>list</code> to see nearby code</li></ul><p>This gives you a full picture of what happened just before failure.</p><h4 id="step-10-tiny-code-assertion-failure-analysis" tabindex="-1">Step 10. Tiny Code: Assertion Failure Analysis <a class="header-anchor" href="#step-10-tiny-code-assertion-failure-analysis" aria-label="Permalink to &quot;Step 10. Tiny Code: Assertion Failure Analysis&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;assert.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int x = 5;</span></span>
<span class="line"><span>    assert(x == 10);  // fails</span></span>
<span class="line"><span>    printf(&quot;Done\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -g assert_fail.c -o assert_fail</span></span>
<span class="line"><span>ulimit -c unlimited</span></span>
<span class="line"><span>./assert_fail</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert_fail: assert_fail.c:5: main: Assertion \`x == 10&#39; failed.</span></span>
<span class="line"><span>Aborted (core dumped)</span></span></code></pre></div><p>Now inspect:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gdb ./assert_fail core</span></span>
<span class="line"><span>(gdb) bt</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#0  0x00007f0a9a4b9187 in raise () from /lib64/libc.so.6</span></span>
<span class="line"><span>#1  0x00007f0a9a4c53e8 in abort () from /lib64/libc.so.6</span></span>
<span class="line"><span>#2  0x00007f0a9a4b0246 in __assert_fail_base () from /lib64/libc.so.6</span></span>
<span class="line"><span>#3  0x00007f0a9a4b02f2 in __assert_fail () from /lib64/libc.so.6</span></span>
<span class="line"><span>#4  0x0000000000401136 in main () at assert_fail.c:5</span></span></code></pre></div><p>You can trace exactly how the assertion caused the abort signal.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Crash analysis turns chaos into clarity. Instead of guessing, you can:</p><ul><li>See which line caused the crash.</li><li>Inspect all variables at that point.</li><li>Reproduce and fix the bug quickly.</li></ul><p>Every serious C programmer must master this, it’s how systems engineers debug everything from user tools to kernels.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Write a small program that dereferences a null pointer.</li><li>Enable core dumps (<code>ulimit -c unlimited</code>).</li><li>Crash it, then analyze the dump in gdb.</li><li>Add one more function layer and check the call chain.</li><li>Experiment with<code>SIGFPE</code>(divide by zero) and see how the core dump differs.</li></ol><p>Next, you’ll build a code review checklist for C projects, habits and principles that help prevent these crashes before they ever happen.</p>`,77)])])}const g=s(t,[["render",p]]);export{u as __pageData,g as default};
